def moving_average(values, window):
    if window <= 0:
        raise ValueError("window must be positive")
    out = []
    for i in range(len(values)):
        lo = max(0, i - (window - 1) // 2)
        hi = min(len(values), i - (window - 1) // 2 + window)
        chunk = values[lo:hi]
        out.append(sum(chunk) / len(chunk))
    return out

